import java.util.TreeMap;

public class TreeMapExplorerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        TreeMap<Integer, String> map = new TreeMap<>();
        map.put(20, "twenty");
        map.put(10, "ten");
        map.put(30, "thirty");
        try {
            check("rangeInfo of three keys", "first=10 last=30", TreeMapExplorer.rangeInfo(map));
            check("floorLabel exact hit", "ten", TreeMapExplorer.floorLabel(map, 10));
            check("floorLabel between keys", "twenty", TreeMapExplorer.floorLabel(map, 25));
            check("floorLabel above all keys", "thirty", TreeMapExplorer.floorLabel(map, 99));
            check("floorLabel below all keys", null, TreeMapExplorer.floorLabel(map, 5));

            TreeMap<Integer, String> single = new TreeMap<>();
            single.put(7, "seven");
            check("rangeInfo single entry", "first=7 last=7", TreeMapExplorer.rangeInfo(single));
            check("floorLabel single entry", "seven", TreeMapExplorer.floorLabel(single, 8));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

