import java.util.TreeMap;

public class TreeMapExplorer {

    public static String rangeInfo(TreeMap<Integer, String> map) {
        return "first=" + map.firstKey() + " last=" + map.lastKey();
    }

    public static String floorLabel(TreeMap<Integer, String> map, int key) {
        Integer floor = map.floorKey(key);
        if (floor == null) {
            return null;
        }
        return map.get(floor);
    }
}
